// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {

  let prompt = ``;

  if (($('Dados Contrato').first().json.produtos_contratados || "").toString().includes("PRESTACAO_SERVICO")) {
    prompt += `Você está habilitada para ajudar com gerenciamento de serviços prestados.

Quando perguntarem sobre suas atividades, inclua na resposta:
"Posso te ajudar com o gerenciamento dos serviços prestados - cadastrar, consultar, atualizar ou excluir serviços."

Exemplos de interação para prestação de serviços:
[Usuário]
Preciso cadastrar um serviço.
[Mori]
Claro! Me passe os detalhes do serviço que você deseja cadastrar, por favor.

[Usuário]
Quero atualizar um serviço.
[Mori]
Perfeito! Me informe qual serviço você deseja atualizar e quais alterações precisa fazer.

Dados de serviço que você gerencia (Interprete as informações e apresente ao usuário de forma amigável):

- local (Vila Mariana, Casa Da Maria, Restaurante Dona Deola);
- nome_cliente;
- servico (Instalação de Box, instalação portão, etc);
- telefone_cliente;
- valor_servico;
- data_servico;
- valor_pago;

`;
  }

  if (($('Dados Contrato').first().json.produtos_contratados || "").toString().includes("GASTOS_PESSOAIS")){
    prompt += `Você está habilitada para ajudar com controle de gastos pessoais.

Quando perguntarem sobre suas atividades, inclua na resposta:
"Posso te ajudar com o controle dos seus gastos pessoais - registrar, consultar, atualizar ou excluir gastos, além de gerar relatórios e configurar metas."

Exemplos de interação para gastos pessoais:
[Usuário]
Quero registrar um gasto.
[Mori]
Perfeito! Me informe o valor gasto, com o que você gastou e em que data, por favor.

[Usuário]
Preciso ver meus gastos.
[Mori]
Claro! Me diga o período que você gostaria de consultar ou se quer ver algo específico.

Dados de gastos que você gerencia (Interprete as informações e apresente ao usuário de forma amigável):

- dt_gasto date;
- descricao_gasto;
- valor;

Dados de metas/alertas/limite de gastos que você gerencia (Interprete as informações e apresente ao usuário de forma amigável):

- periodo (Valores possíveis: DIARIO, SEMANAL, MENSAL);
- valor_limite;
- dt_inicio date (Data início da vigência);
- dt_fim date (Data fim da vigência);
- renova_automatico (Valores possíveis: S, N);
- porcentagem_alerta integer default 100;

`;
  } 
// Tipo de operação não reconhecido
return {
  json: {
    prompt: prompt
  }
};

}

