// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {

  let prompt_out = ``;

  if ($input.first().json.output === "GASTO-CRIAR") {
    prompt_out = `### **GASTO-CRIAR** (Registrar novos gastos)
**Exemplo de contexto**: Usuário diz "Gastei 10 reais com um salgado"
**Mensagens de status**:
- "Ok, vou registrar sua solicitação no banco, só um instante."
- "Entendi! Processando seu gasto..."
- "Certo, aguarde um momento enquanto registro isso."`;
  } 

  if ($input.first().json.output === "GASTO-CONSULTAR"){
    prompt_out = `### **GASTO-CONSULTAR** (Buscar/visualizar gastos)
**Exemplo de contexto**: Usuário pergunta "Quanto gastei este mês?"
**Mensagens de status**:
- "Ok, vou consultar seus gastos, só um segundo..."
- "Claro, vou buscar essas informações para você!"
- "Claro! Aguarde só um minutinho, estou verificando seu histórico..."`;
  } 

  if ($input.first().json.output === "GASTO-ATUALIZAR"){
    prompt_out = `### **GASTO-ATUALIZAR** (Modificar gastos existentes)
**Exemplo de contexto**: Usuário diz "Quero corrigir aquele gasto de ontem"
**Mensagens de status**:
- "Pode deixar, vou realizar a alteração, aguarde só um minuto..."
- "Ok, vou atualizar o registro para você."
- "Entendi, vou fazer a correção..."`;
  } 

  if ($input.first().json.output === "GASTO-DELETAR"){
    prompt_out = `### **GASTO-DELETAR** (Excluir gastos)
**Exemplo de contexto**: Usuário pede "Remove esse gasto duplicado"
**Mensagens de status**:
- "Vou remover o registro, só um momento..."
- "Ok, vou processar a exclusão."
- "Entendido, vou deletar..."`;
  } 

  if ($input.first().json.output === "META-CRIAR"){
    prompt_out = `### **META-CRIAR** (Criar metas/alertas/limites)
**Exemplo de contexto**: Usuário diz "Quero criar um limite de R$ 500 para alimentação"
